# Model initialization
model = BirdCLEFModel(num_conv_layers=num_conv_layers, dropout_rate=dropout_rate).to('cuda')
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=0.0001)  # L2 regularization

# Training loop
epochs = 2
model.train()
train_losses = []

for epoch in range(epochs):
    for batch_idx, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels)
        loss.backward()
        optimizer.step()
        
        train_losses.append(loss.item())
        print(f"Epoch {epoch + 1}/{epochs}, Batch {batch_idx + 1}: Loss: {loss.item():.4f}")
        
        torch.cuda.empty_cache()  # Prevent GPU fragmentation
        
        # Limit to first ~5000 samples for fast feedback
        if batch_idx >= (5000 // batch_size) - 1:
            break

# Validation loop
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in train_loader:  # Use same loader in eval mode
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        outputs = model(inputs)
        
        all_preds.append(outputs.cpu().numpy())
        all_labels.append(labels.cpu().numpy())


all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)
final_auc = roc_auc_score(all_labels, all_preds, average='weighted')

# Metrics and model saving
num_params = sum(p.numel() for p in model.parameters() if p.requires_grad)
